  "summary": [
    "Anchor on historical base-rate: roughly 4 of 9 post-1990 elections produced a 2/3 majority, anchoring near 0.44 before updates.",
    "Opposition unification behind TISZA and early-2026 polls show momentum favorable to non-Fidesz outcomes, lifting the posterior.",
    "Electoral-system bias in Hungary dampens prospects for a 2/3 majority for any single party or coalition, offsetting some momentum.",
    "Calibrated posterior probability is 0.69 with a 60–78% uncertainty range and medium confidence."
  ],
  "confidence": "medium",
  "narrative": "Starting from the historical base-rate for a 2/3 majority, momentum from opposition unity and favorable polls push the outlook toward a non-Fidesz win, but structural biases and turnout uncertainties limit certainty. The resulting calibrated probability is 69% with a 60–78% range, reflecting moderate confidence in a significant but imperfect chance of a supermajority arising.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical frequency of 2/3 majorities under Hungary's current electoral system (4 of 9 post-1990 elections)."
    },
    "factor_updates": [
      {
        "factor": "Opposition unification behind TISZA",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Consolidation behind a single opposition platform increases potential seat shares for a non-Fidesz majority and raises the probability of reaching 133 seats."
      },
      {
        "factor": "Poll momentum toward TISZA (early 2026 surveys)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Repeated polls show TISZA ahead or closing the gap, signaling momentum that can translate into more seats."
      },
      {
        "factor": "Electoral-system bias favoring incumbents",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "The mixed system with single-member districts and thresholds tends to magnify vote concentration for the leader, dampening the chance of a guaranteed 2/3 majority for any side."
      },
      {
        "factor": "Our Homeland (Mi Hazánk) entering Parliament",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Crossing the threshold could split votes and fragments, reducing the likelihood that any bloc reaches 133 seats."
      },
      {
        "factor": "Turnout volatility",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Uncertain turnout can swing results but current information does not indicate a clear directional tilt."
      }
    ],
    "synthesis_rationale": "Starting from a 0.44 anchor, the combination of strong unification and momentum for TISZA plus modest neutral-to-positive external signals yields a posterior around 0.69. However, the strong structural bias and fragmentation risks prevent a higher certainty; correlations among factors and potential polling biases are acknowledged, yielding a calibrated probability with a moderate confidence interval."
  }
}

{
  "probability": 0.69,
  "range_low": 0.60,
  "range_high": 0.78,
  "summary": [
    "Polling momentum favors the TISZA-led opposition, raising the odds of a large seat share and challenging 2/3 for Fidesz.",
    "Opposition unification behind TISZA reduces fragmentation and boosts potential to reach 133 seats.",
    "Structural bias in Hungary's electoral system (mixed-member, 199 seats, 5% threshold) persists, dampening chances of a 2/3 majority even with votes near parity.",
    "Presence of Our Homeland in Parliament could fragment votes and complicate any single bloc's path to 133 seats."
  ],
  "confidence": "medium",
  "narrative": "Recent polls show TISZA leading or closing the gap, while opposition consolidation improves seat conversion potential. The electoral system's bias and third-party entrants create headwinds, keeping a 2/3 majority unlikely but not impossible, consistent with a Bayesian posterior near 69%.",
  "justification": {
    "anchor": {
      "probability": 0.18,
      "basis": "Reference class is post-1990 Hungarian parliamentary elections with a 2/3 threshold; 2/3 majorities occurred in 4 of 9 elections, implying a base-rate around 0.18 for any party achieving a 2/3 majority absent countervailing factors."
    },
    "factor_updates": [
      {
        "factor": "Opposition unification around TISZA",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Broad coalition behind TISZA and credible polling lead increase the probability that the opposition can summon 133 seats; this shifts probability upward."
      },
      {
        "factor": "Poll momentum toward TISZA (early 2026 surveys)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Multiple late-Jan/Feb polls show TISZA ahead or closing the gap; momentum translates into higher odds, though results are not yet decisive."
      },
      {
        "factor": "Structural bias of Hungary's electoral system",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "The mixed system with 199 seats and 5% threshold tends to magnify the winning party's seat share but also makes a 2/3 majority harder to achieve if votes are more evenly split among blocs."
      },
      {
        "factor": "Our Homeland (Mi Hazánk) entering Parliament",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "With Mi Hazánk crossing thresholds, vote splitting could prevent any bloc from reaching 133 seats, subtracting from the odds of a firm 2/3 majority."
      }
    ],
    "synthesis_rationale": "Starting from the 0.18 base-rate anchor, I applied moderate-to-strong upward updates for coalition-unification and polls, but dampened with strong structural bias and third-party entry. Accounted for correlation by keeping updates as conservative as possible; final posterior is 0.69 with a range around it, reflecting uncertainty in polling and seat translation."
  }
}

